#include "yuv2rgb.cuh"

__device__ inline float clamp(float val, float mn, float mx)
{
	return (val >= mn)? ((val <= mx)? val : mx) : mn;
}


__global__ void gpuConvertYUYVtoRGB_kernel(unsigned char *src, unsigned char *dst,
		unsigned int width, unsigned int height, int width_downsamplerate, int height_downsamplerate)
{
	int idx = blockIdx.x * blockDim.x + threadIdx.x;
	if (idx*2 >= width) {
		return;
	}

	for (int i = 0; i < height; ++i) {
		if (i % 2 == 1) {
			continue;
		}
		{
			int y0 = src[i*width*2+idx*4*2+0];
			int cb = src[i*width*2+idx*4*2+1];
			//int y1 = src[i*width*2+idx*4*2+2];
			int cr = src[i*width*2+idx*4*2+3];

			dst[i*width*3/2+idx*6+0] = clamp(1.164f * (y0 - 16) + 1.596f * (cr - 128)                      , 0.0f, 255.0f);
			dst[i*width*3/2+idx*6+1] = clamp(1.164f * (y0 - 16) - 0.813f * (cr - 128) - 0.391f * (cb - 128), 0.0f, 255.0f);
			dst[i*width*3/2+idx*6+2] = clamp(1.164f * (y0 - 16)                       + 2.018f * (cb - 128), 0.0f, 255.0f);
		}
		{
			int y0 = src[i*width*2+idx*4*2+4];
			int cb = src[i*width*2+idx*4*2+5];
			//int y1 = src[i*width*2+idx*4*2+6];
			int cr = src[i*width*2+idx*4*2+7];

			dst[i*width*3/2+idx*6+3] = clamp(1.164f * (y0 - 16) + 1.596f * (cr - 128)                      , 0.0f, 255.0f);
			dst[i*width*3/2+idx*6+4] = clamp(1.164f * (y0 - 16) - 0.813f * (cr - 128) - 0.391f * (cb - 128), 0.0f, 255.0f);
			dst[i*width*3/2+idx*6+5] = clamp(1.164f * (y0 - 16)                       + 2.018f * (cb - 128), 0.0f, 255.0f);
		}

	}
}


void gpuConvertYUYVtoRGB(unsigned char *src, unsigned char *dst,
		unsigned int width, unsigned int height, int width_downsamplerate, int height_downsamplerate)
{
	unsigned char *d_src = NULL;
	unsigned char *d_dst = NULL;
	size_t planeSize = width * height * sizeof(unsigned char);

	unsigned int flags;
	bool srcIsMapped = (cudaHostGetFlags(&flags, src) == cudaSuccess) && (flags & cudaHostAllocMapped);
	bool dstIsMapped = (cudaHostGetFlags(&flags, dst) == cudaSuccess) && (flags & cudaHostAllocMapped);

	if (srcIsMapped) {
		d_src = src;
		cudaStreamAttachMemAsync(NULL, src, 0, cudaMemAttachGlobal);
	} else {//主程序的yuv_不是cuda的，所以走else
		cudaMalloc(&d_src, planeSize * 2);
		cudaMemcpy(d_src, src, planeSize * 2, cudaMemcpyHostToDevice);//这部分cpu/内存到gpu/显存的拷贝预计占用较大的时间，也没有什么好办法降低（既然cpu里面抽帧效果是不成功的）
	}
	if (dstIsMapped) {//这部分zero cpy，应该走的是这个分支
		d_dst = dst;
		cudaStreamAttachMemAsync(NULL, dst, 0, cudaMemAttachGlobal);
	} else {
		cudaMalloc(&d_dst, planeSize * 3);
	}

	unsigned int blockSize = 1024;
	unsigned int numBlocks = (width / 2 / width_downsamplerate + blockSize - 1) / blockSize;//因为源大小不变，抽帧应该不影响此处size和blocks
	gpuConvertYUYVtoRGB_kernel<<<numBlocks, blockSize>>>(d_src, d_dst, width, height, width_downsamplerate, height_downsamplerate);
	cudaStreamAttachMemAsync(NULL, dst, 0, cudaMemAttachHost);
	cudaStreamSynchronize(NULL);

	if (!srcIsMapped) {//主程序的yuv_不是cuda的，所以走这个分支
		cudaMemcpy(dst, d_dst, planeSize * 3, cudaMemcpyDeviceToHost);
		cudaFree(d_src);
	}
	if (!dstIsMapped) {//这部分zero cpy，应该不走这个分支
		cudaFree(d_dst);
	}
}

